import subprocess, sys, time, urllib.request, urllib.error

def req(path):
    r = urllib.request.Request(f'http://127.0.0.1:8015{path}')
    try:
        with urllib.request.urlopen(r, timeout=3) as resp:
            return resp.status, resp.read().decode(errors='replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode(errors='replace')

srv = subprocess.Popen([sys.executable, '-m', 'uvicorn', 'app:app', '--port', '8015'])
try:
    ok = False
    for _ in range(30):
        try:
            status, body = req('/download/hello.txt')
            ok = True
            break
        except (urllib.error.URLError, ConnectionResetError):
            time.sleep(0.5)
    assert ok, 'server never became reachable on :8015'
    assert status == 200, f'expected 200 for legitimate file, got {status}'
    assert 'hello from files dir' in body, f'unexpected body: {body!r}'

    status, body = req('/download/..%2Fsecret.txt')
    assert status >= 400, f'expected an error status for traversal attempt, got {status} body={body!r}'
    assert 'top secret' not in body, f'traversal leaked secret file contents: {body!r}'

    status2, body2 = req('/download/..%2F..%2Fsecret.txt')
    assert status2 >= 400 or 'top secret' not in body2, 'traversal with doubled dots leaked secret contents'
finally:
    srv.terminate()
    try:
        srv.wait(timeout=5)
    except Exception:
        srv.kill()
print('PASS')

